arguments.file_text:
namespace sv_0d82220a1382431b91db34a0073c90d2.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_0d82220a1382431b91db34a0073c90d2.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    @* Left Sidebar - Channel List *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (channels is not null)
            {
                @foreach (var channel in channels)
                {
                    <li class="channel-item @(channel.Id == activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannel(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-description">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* Main Message Area *@
    <main class="message-area @(threadOpen ? "thread-open" : "")">
        @if (activeChannel is not null)
        {
            <div class="message-header">
                <h2># @activeChannel.Name</h2>
                <p>@activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @if (messages is not null)
                {
                    @foreach (var message in messages)
                    {
                        <div class="message-item" @onmouseenter="() => hoveredMessageId = message.Id"
                             @onmouseleave="() => hoveredMessageId = null">
                            <div class="message-content-wrapper">
                                <div class="message-meta">
                                    <strong class="message-author">@message.Author</strong>
                                    <span class="message-time">@FormatRelativeTime(message.SentAt)</span>
                                </div>
                                <div class="message-text">@message.Content</div>

                                @if (message.Reactions.Any())
                                {
                                    <div class="reaction-row">
                                        @foreach (var reaction in message.Reactions)
                                        {
                                            <button class="reaction-badge" @onclick="() => AddReaction(message.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @if (threadSummaries.TryGetValue(message.Id, out var summary))
                                {
                                    <button class="thread-link" @onclick="() => OpenThread(message)">
                                        @summary.ReplyCount replies
                                    </button>
                                }
                            </div>

                            @if (hoveredMessageId == message.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThread(message)" title="Reply in thread">
                                        💬
                                    </button>
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(message.Id)" title="Add reaction">
                                        😀
                                    </button>
                                </div>

                                @if (emojiPickerMessageId == message.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in commonEmojis)
                                        {
                                            <button class="emoji-option" @onclick="() => AddReaction(message.Id, emoji)">
                                                @emoji
                                            </button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="newMessageContent" @bind:event="oninput"
                          @onkeydown="HandleMessageKeyDown"
                          placeholder="Type a message..." rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(newMessageContent)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* Right Panel - Thread View *@
    @if (threadOpen && threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            <div class="thread-root-message">
                <strong>@threadRootMessage.Author</strong>
                <span class="message-time">@FormatRelativeTime(threadRootMessage.SentAt)</span>
                <p>@threadRootMessage.Content</p>
            </div>

            <div class="thread-replies">
                @if (threadMessages is not null)
                {
                    @foreach (var reply in threadMessages)
                    {
                        <div class="message-item thread-reply">
                            <div class="message-meta">
                                <strong class="message-author">@reply.Author</strong>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-text">@reply.Content</div>
                            @if (reply.Reactions.Any())
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <button class="reaction-badge" @onclick="() => AddReaction(reply.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="threadReplyContent" @bind:event="oninput"
                          @onkeydown="HandleThreadKeyDown"
                          placeholder="Reply in thread..." rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReply" disabled="@string.IsNullOrWhiteSpace(threadReplyContent)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel>? channels;
    private List<Message>? messages;
    private List<Message>? threadMessages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private Channel? activeChannel;
    private int activeChannelId;
    private Message? threadRootMessage;
    private bool threadOpen;
    private string newMessageContent = "";
    private string threadReplyContent = "";
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;
    private ElementReference messageListRef;

    private static readonly string[] commonEmojis = { "👍", "❤️", "😂", "🎉", "🤔", "👀" };

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannel = channel;
        activeChannelId = channel.Id;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await BuildThreadSummaries();
        await ScrollToBottom();
    }

    private async Task BuildThreadSummaries()
    {
        threadSummaries.Clear();
        if (messages is null) return;

        // Identify messages that have replies (messages whose Id is referenced by ReplyToId)
        var rootIds = messages
            .Where(m => m.ReplyToId.HasValue)
            .Select(m => m.ReplyToId!.Value)
            .Distinct()
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            var replies = messages.Where(m => m.ReplyToId == rootId).ToList();
            if (replies.Any())
            {
                threadSummaries[rootId] = new ThreadSummary(
                    rootId,
                    replies.Count,
                    replies.Max(r => r.SentAt)
                );
            }
        }
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 10 && !isLoadingMore && activeChannel is not null)
        {
            await LoadOlderMessages();
        }
    }

    private async Task LoadOlderMessages()
    {
        if (activeChannel is null || messages is null) return;

        isLoadingMore = true;
        StateHasChanged();

        messageSkip += PageSize;
        var olderMessages = await ChatService.GetMessagesAsync(activeChannel.Id, messageSkip, PageSize);
        if (olderMessages.Any())
        {
            messages.InsertRange(0, olderMessages);
            await BuildThreadSummaries();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessageContent) || activeChannel is null) return;

        var sent = await ChatService.SendMessageAsync(activeChannel.Id, newMessageContent.Trim(), null);
        messages ??= new();
        messages.Add(sent);
        newMessageContent = "";
        await ScrollToBottom();
    }

    private async Task HandleMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessage();
        }
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReply();
        }
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadOpen = true;
        emojiPickerMessageId = null;
        threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = null;
    }

    private async Task SendThreadReply()
    {
        if (string.IsNullOrWhiteSpace(threadReplyContent) || threadRootMessage is null || activeChannel is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannel.Id, threadReplyContent.Trim(), threadRootMessage.Id);
        threadMessages ??= new();
        threadMessages.Add(reply);
        threadReplyContent = "";

        // Update thread summary count
        if (threadSummaries.ContainsKey(threadRootMessage.Id))
        {
            var existing = threadSummaries[threadRootMessage.Id];
            threadSummaries[threadRootMessage.Id] = existing with { ReplyCount = existing.ReplyCount + 1, LastReplyAt = reply.SentAt };
        }
        else
        {
            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt);
        }
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, messageSkip + PageSize);
        }

        // Also refresh thread if open
        if (threadOpen && threadRootMessage is not null)
        {
            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task ScrollToBottom()
    {
        await Task.Delay(50); // Allow render to complete
        await JS.InvokeVoidAsync("eval", "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list').scrollHeight)");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hr ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays} days ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

.sidebar-header h3 {
